\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(condition boolean,message text) returns void language plpgsql as $$ begin if condition is distinct from true then raise exception 'ASSERT: %',message; end if; end $$;
insert into auth.users(id) select ('00000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid from generate_series(1,7) i;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select public.app_action('create_team','{"name":"测试小队","timezone":"Asia/Shanghai"}');
create temp table test_context as select app.team_for(auth.uid()) team_id, (public.app_action('create_invite')->>'token') token;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select public.app_action('join_team',jsonb_build_object('token',token)) from test_context;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select public.app_action('join_team',jsonb_build_object('token',token)) from test_context;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select public.app_action('join_team',jsonb_build_object('token',token)) from test_context;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select public.app_action('join_team',jsonb_build_object('token',token)) from test_context;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000006',true);
do $$ begin perform public.app_action('join_team',jsonb_build_object('token',(select token from test_context))); raise exception 'full team accepted'; exception when raise_exception then if sqlerrm<>'小队已满 5 人' then raise; end if; end $$;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select public.app_action('save_plan','{"title":"学习","category":"study","weekdays":[1,2,3,4,5,6,7],"start_time":"00:00","deadline":"23:50","visibility":"team","status":"active"}');
select public.app_action('save_plan','{"title":"饮食","category":"food","weekdays":[1,2,3,4,5,6,7],"start_time":"00:00","deadline":"23:50","visibility":"private","status":"active"}');
select public.app_action('save_plan','{"title":"运动","category":"exercise","weekdays":[1,2,3,4,5,6,7],"start_time":"00:00","deadline":"23:50","visibility":"team","status":"active"}');
select public.app_action('save_plan','{"title":"第四个","category":"custom","weekdays":[1],"start_time":"08:00","deadline":"21:00"}');
insert into public.media(id,user_id,team_id,batch_id,path,source,captured_at,local_date,phash)
select '10000000-0000-4000-8000-000000000001',auth.uid(),team_id,'20000000-0000-4000-8000-000000000001','test/a.jpg','camera',now(),(now() at time zone 'Asia/Shanghai')::date,'hash0001' from test_context;
create temp table submitted as select public.app_action('submit_checkin',jsonb_build_object('media_ids',jsonb_build_array('10000000-0000-4000-8000-000000000001'),'plan_id',(select id from public.plans where title='学习'),'idempotency_key','integration-submit-1')) result;
select pg_temp.assert_true((select count(*)=1 from public.checkins),'one stamp');
select pg_temp.assert_true((select status='stamped' and memo_status='pending' from public.checkins),'AI not a stamp gate');
select public.app_action('submit_checkin',jsonb_build_object('media_ids',jsonb_build_array('10000000-0000-4000-8000-000000000001'),'idempotency_key','integration-submit-1'));
select pg_temp.assert_true((select count(*)=1 from public.checkins),'idempotent submit');
select pg_temp.assert_true(not app.validate_fields('[{"key":"calories","label":"热量","value":501,"source":"ai"}]','food'),'no precise calorie');
select pg_temp.assert_true(not app.validate_fields('[{"key":"duration","label":"时长","value":30,"source":"ai"}]','exercise'),'no AI exercise duration');
select pg_temp.assert_true(app.validate_fields('[{"key":"calories","label":"热量","value":{"min":450,"max":650,"estimated":true},"source":"ai"}]','food'),'range accepted');
do $$ begin perform public.app_action('interact',jsonb_build_object('checkin_id',(select id from public.checkins limit 1),'kind','challenge','content','本人质疑')); raise exception 'self challenge accepted'; exception when raise_exception then if sqlerrm<>'不能质疑自己的记录' then raise; end if; end $$;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
do $$ begin perform public.app_action('interact',jsonb_build_object('checkin_id',(select id from public.checkins limit 1),'kind','challenge','content','')); raise exception 'empty reason accepted'; exception when raise_exception then if sqlerrm<>'请写一句具体理由' then raise; end if; end $$;
select public.app_action('interact',jsonb_build_object('checkin_id',(select id from public.checkins limit 1),'kind','challenge','content','内容不清楚'));
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select public.app_action('interact',jsonb_build_object('checkin_id',(select id from public.checkins limit 1),'kind','challenge','content','请补充照片'));
select pg_temp.assert_true((select status='stamped' from public.checkins),'2 of 5 does not change state');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select public.app_action('interact',jsonb_build_object('checkin_id',(select id from public.checkins limit 1),'kind','challenge','content','证据不完整'));
select pg_temp.assert_true((select status='redo_required' and redo_deadline is not null from public.checkins),'3 of 5 triggers redo');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000006',true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=0 from public.checkins),'RLS outsider isolation');
select pg_temp.assert_true((select count(*)=0 from public.media),'RLS media isolation');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select public.app_action('edit_memo',jsonb_build_object('checkin_id',(select id from public.checkins limit 1),'summary','本人修改','fields','[]'::jsonb));
select public.apply_ai_result((select id from public.checkins limit 1),'{"version":1,"assignments":[],"groups":[]}');
select pg_temp.assert_true((select summary='本人修改' from public.checkins),'stale AI cannot overwrite user');
select public.run_schedule(((now() at time zone 'Asia/Shanghai')::date+time '23:31') at time zone 'Asia/Shanghai');
select pg_temp.assert_true((select count(*)=2 from public.overdue_feed),'23:30 cap and private plan excluded');
select public.run_schedule(((now() at time zone 'Asia/Shanghai')::date+time '23:31') at time zone 'Asia/Shanghai');
select pg_temp.assert_true((select count(*)=2 from public.overdue_feed),'scheduler idempotency');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select public.app_action('poke',jsonb_build_object('overdue_id',(select id from public.overdue_feed limit 1)));
select public.app_action('poke',jsonb_build_object('overdue_id',(select id from public.overdue_feed limit 1)));
select pg_temp.assert_true((select count(*)=1 from public.pokes),'one poke per member');
select public.app_action('leave_team');
set local role authenticated;
select pg_temp.assert_true((select count(*)=0 from public.checkins),'left member loses team history access');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true(public.bootstrap() ? 'profile','bootstrap contract');
select app.build_report(auth.uid(),date_trunc('week',now() at time zone 'Asia/Shanghai')::date,'Asia/Shanghai');
select pg_temp.assert_true((select count(*)=1 from public.reports where kind='personal'),'report generation');
select pg_temp.assert_true(not has_function_privilege('authenticated','public.apply_ai_result(uuid,jsonb)','execute'),'AI RPC not exposed');
select pg_temp.assert_true(not has_function_privilege('authenticated','public.reserve_photo(uuid,uuid,text,text,text,timestamptz,text,jsonb)','execute'),'metadata cannot be forged via RPC');
select public.prepare_account_deletion();
select pg_temp.assert_true((select deletion_requested_at is not null from public.profiles where id=auth.uid()),'deletion marker persists before external cleanup');
do $$ begin
 perform public.app_action('save_profile','{"nickname":"不应写入"}');
 raise exception 'accepted writes during deletion';
 exception when raise_exception then if sqlerrm<>'账号删除尚未完成，请在设置中再次删除以继续清理' then raise; end if;
end $$;
do $$ begin
 insert into storage.objects(bucket_id,name) values('evidence',auth.uid()::text||'/racing.jpg');
 raise exception 'accepted storage during deletion';
 exception when raise_exception then if sqlerrm<>'账号正在删除，无法继续上传' then raise; end if;
end $$;
delete from auth.users where id=auth.uid();
select pg_temp.assert_true((select count(*)=0 from public.checkins),'account removal cascades records');
rollback;
\echo 'PASS integration: transactional rules, RLS, jobs, privacy, account deletion'
